[{"order":1,"type":"heading","text":"React Hook Form: Performant Form Handling"},{"order":2,"type":"subheading","text":"Introduction"},{"order":3,"type":"paragraph","text":"React Hook Form is a library for building performant and flexible forms in React. It leverages React's uncontrolled components and refs, minimizing re-renders and improving performance compared to traditional controlled component approaches. This tutorial will guide you through the core concepts and demonstrate how to use React Hook Form effectively."},{"order":4,"type":"subheading","text":"Why React Hook Form?"},{"order":5,"type":"bullet_point","text":"Performance: Reduces re-renders by using uncontrolled components."},{"order":6,"type":"bullet_point","text":"Simplicity: Provides a clean and intuitive API."},{"order":7,"type":"bullet_point","text":"Validation: Built-in support for validation using various methods (e.g., Yup, Zod, Joi)."},{"order":8,"type":"bullet_point","text":"TypeScript Support: Excellent TypeScript support for type safety."},{"order":9,"type":"subheading","text":"Installation"},{"order":10,"type":"paragraph","text":"Install React Hook Form using npm or yarn:"},{"order":11,"type":"code","text":"npm install react-hook-form"},{"order":12,"type":"code","text":"yarn add react-hook-form"},{"order":13,"type":"subheading","text":"Basic Usage"},{"order":14,"type":"paragraph","text":"Let's start with a simple form example:"},{"order":15,"type":"code","text":"import React from 'react';
import { useForm } from 'react-hook-form';

function MyForm() {
  const { register, handleSubmit, formState: { errors } } = useForm();

  const onSubmit = (data) => {
    console.log(data);
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)}>
      <label htmlFor="firstName">First Name:</label>
      <input type="text" id="firstName" {...register("firstName", { required: true })} />
      {errors.firstName && <span>This field is required</span>}

      <label htmlFor="lastName">Last Name:</label>
      <input type="text" id="lastName" {...register("lastName")} />

      <button type="submit">Submit</button>
    </form>
  );
}

export default MyForm;"},{"order":16,"type":"paragraph","text":"Explanation:"},{"order":17,"type":"bullet_point","text":"`useForm`: This hook provides the core functionality for managing the form state."},{"order":18,"type":"bullet_point","text":"`register`: This function is used to register an input field with React Hook Form.  It returns props that you spread onto your input element. The first argument is the name of the field.  The second argument is an optional object containing validation rules."},{"order":19,"type":"bullet_point","text":"`handleSubmit`: This function handles the form submission. It takes a callback function as an argument, which will be executed with the form data when the form is submitted successfully."},{"order":20,"type":"bullet_point","text":"`formState.errors`: This object contains any validation errors that occur."},{"order":21,"type":"subheading","text":"Validation"},{"order":22,"type":"paragraph","text":"React Hook Form offers built-in validation capabilities. You can specify validation rules when registering input fields."},{"order":23,"type":"code","text":"<input type="email" {...register("email", { required: "Email is required", pattern: {value: /^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$/, message: "Invalid email address"} })} />
{errors.email && <p>{errors.email.message}</p>}"},{"order":24,"type":"paragraph","text":"In this example:"},{"order":25,"type":"bullet_point","text":"`required`: Makes the field mandatory.  The string value will be the error message."},{"order":26,"type":"bullet_point","text":"`pattern`: Validates the field against a regular expression.  `value` contains the regex, and `message` the error message."},{"order":27,"type":"subheading","text":"Using Validation Libraries (Yup, Zod)"},{"order":28,"type":"paragraph","text":"For more complex validation scenarios, you can integrate React Hook Form with validation libraries like Yup or Zod. This provides a more structured and maintainable approach to validation."},{"order":29,"type":"subheading","text":"Yup Integration"},{"order":30,"type":"paragraph","text":"First, install Yup:"},{"order":31,"type":"code","text":"npm install yup"},{"order":32,"type":"paragraph","text":"Then, create a Yup schema and use the `useForm` hook with the `resolver` option:"},{"order":33,"type":"code","text":"import React from 'react';
import { useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import * as yup from 'yup';

const schema = yup.object({
  firstName: yup.string().required('First Name is required'),
  lastName: yup.string(),
  age: yup.number().positive().integer().required('Age is required'),
});

function YupForm() {
  const { register, handleSubmit, formState: { errors } } = useForm({
    resolver: yupResolver(schema),
  });

  const onSubmit = (data) => {
    console.log(data);
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)}>
      <label htmlFor="firstName">First Name:</label>
      <input type="text" id="firstName" {...register("firstName")} />
      {errors.firstName && <span>{errors.firstName.message}</span>}

      <label htmlFor="lastName">Last Name:</label>
      <input type="text" id="lastName" {...register("lastName")} />

      <label htmlFor="age">Age:</label>
      <input type="number" id="age" {...register("age")} />
      {errors.age && <span>{errors.age.message}</span>}

      <button type="submit">Submit</button>
    </form>
  );
}

export default YupForm;"},{"order":34,"type":"paragraph","text":"Explanation:"},{"order":35,"type":"bullet_point","text":"`yupResolver`: This function from `@hookform/resolvers/yup` integrates Yup with React Hook Form."},{"order":36,"type":"bullet_point","text":"The `schema` defines the validation rules using Yup's API."},{"order":37,"type":"subheading","text":"Zod Integration"},{"order":38,"type":"paragraph","text":"First, install Zod:"},{"order":39,"type":"code","text":"npm install zod"},{"order":40,"type":"paragraph","text":"Then, create a Zod schema and use the `useForm` hook with the `resolver` option:"},{"order":41,"type":"code","text":"import React from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';

const schema = z.object({
  firstName: z.string().min(1, { message: "First Name is required" }),
  lastName: z.string().optional(),
  age: z.number().min(0, { message: "Age must be positive" }).int().required("Age is required"),
});

type FormData = z.infer<typeof schema>;

function ZodForm() {
  const { register, handleSubmit, formState: { errors } } = useForm<FormData>({
    resolver: zodResolver(schema),
  });

  const onSubmit = (data) => {
    console.log(data);
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)}>
      <label htmlFor="firstName">First Name:</label>
      <input type="text" id="firstName" {...register("firstName")} />
      {errors.firstName && <span>{errors.firstName.message}</span>}

      <label htmlFor="lastName">Last Name:</label>
      <input type="text" id="lastName" {...register("lastName")} />

      <label htmlFor="age">Age:</label>
      <input type="number" id="age" {...register("age")} />
      {errors.age && <span>{errors.age.message}</span>}

      <button type="submit">Submit</button>
    </form>
  );
}

export default ZodForm;"},{"order":42,"type":"paragraph","text":"Explanation:"},{"order":43,"type":"bullet_point","text":"`zodResolver`: This function from `@hookform/resolvers/zod` integrates Zod with React Hook Form."},{"order":44,"type":"bullet_point","text":"The `schema` defines the validation rules using Zod's API.  We also create a `FormData` type using `z.infer` to give us full type safety."},{"order":45,"type":"subheading","text":"Handling Asynchronous Validation"},{"order":46,"type":"paragraph","text":"For asynchronous validation (e.g., checking if a username is available), you can use the `validate` option in `register`."},{"order":47,"type":"code","text":"import React from 'react';
import { useForm } from 'react-hook-form';

async function checkUsernameAvailability(username) {
  // Simulate an API call
  await new Promise(resolve => setTimeout(resolve, 500));
  return username === 'taken'; // Simulate username being taken
}

function AsyncValidationForm() {
  const { register, handleSubmit, formState: { errors } } = useForm();

  const onSubmit = (data) => {
    console.log(data);
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)}>
      <label htmlFor="username">Username:</label>
      <input
        type="text"
        id="username"
        {...register("username", {
          validate: async (value) => {
            const isTaken = await checkUsernameAvailability(value);
            return isTaken ? 'Username is already taken' : true;
          },
        })}
      />
      {errors.username && <span>{errors.username.message}</span>}

      <button type="submit">Submit</button>
    </form>
  );
}

export default AsyncValidationForm;"},{"order":48,"type":"paragraph","text":"Explanation:"},{"order":49,"type":"bullet_point","text":"The `validate` option accepts an asynchronous function that returns `true` if the validation passes, or an error message string if it fails."},{"order":50,"type":"subheading","text":"setValue and watch"},{"order":51,"type":"paragraph","text":"`setValue` allows you to programmatically set the value of a field. `watch` allows you to subscribe to changes in a specific field or the entire form."},{"order":52,"type":"code","text":"import React from 'react';
import { useForm } from 'react-hook-form';

function SetValueWatchForm() {
  const { register, handleSubmit, setValue, watch } = useForm();

  const onSubmit = (data) => {
    console.log(data);
  };

  const handleButtonClick = () => {
    setValue('firstName', 'John');
  };

  const firstNameValue = watch('firstName');

  return (
    <form onSubmit={handleSubmit(onSubmit)}>
      <label htmlFor="firstName">First Name:</label>
      <input type="text" id="firstName" {...register("firstName")} />

      <button type="button" onClick={handleButtonClick}>Set First Name to John</button>

      <p>First Name Value: {firstNameValue}</p>

      <button type="submit">Submit</button>
    </form>
  );
}

export default SetValueWatchForm;"},{"order":53,"type":"paragraph","text":"Explanation:"},{"order":54,"type":"bullet_point","text":"`setValue('firstName', 'John')`: Sets the value of the 'firstName' field to 'John'."},{"order":55,"type":"bullet_point","text":"`watch('firstName')`: Subscribes to changes in the 'firstName' field and returns its current value."},{"order":56,"type":"subheading","text":"Conclusion"},{"order":57,"type":"paragraph","text":"React Hook Form provides a performant and flexible way to handle forms in React. Its simple API, combined with its ability to integrate with validation libraries, makes it a powerful tool for building complex forms with ease. By leveraging uncontrolled components and refs, React Hook Form minimizes re-renders and optimizes form performance, resulting in a better user experience."}]
